def vote_tile(inp,ph,pw):
    H,W=inp.shape
    maj=np.zeros((ph,pw),dtype=int)
    cnt=np.zeros((ph,pw),dtype=int)
    for r in range(H):
        for c in range(W):
            maj[r%ph,c%pw]+=inp[r][c]; cnt[r%ph,c%pw]+=1
    return maj/cnt

