    best=[]
    for ph in range(1,H+1):
        for pw in range(1,W+1):
            tile=vote_tile(gi,ph,pw)
            pred=np.tile(tile,(H//ph+1,W//pw+1))[:,:H,:][:,:W] if False else None
            if W%pw!=0 or H%ph!=0: break
            pred=np.tile(tile,(H//ph,W//pw))
            sc=float(np.mean(pred==gi))
            best.append((sc,ph,pw))
    best.sort(reverse=True)
